// Turns the raw insights rows into totals plus a per-campaign table.
const settings = $('Settings').first().json;
const rows = $input.first().json.data || [];
const num = (v) => Number(v || 0);
const resultsOf = (actions) => num((actions || []).find((a) => a.action_type === settings.result_action)?.value);

const campaigns = rows
  .map((r) => {
    const spend = num(r.spend);
    const results = resultsOf(r.actions);
    return {
      name: r.campaign_name,
      spend: +spend.toFixed(2),
      impressions: num(r.impressions),
      clicks: num(r.clicks),
      ctr_pct: +num(r.ctr).toFixed(2),
      cpc: +num(r.cpc).toFixed(2),
      results,
      cost_per_result: results ? +(spend / results).toFixed(2) : null,
    };
  })
  .sort((a, b) => b.spend - a.spend);

const sum = (key) => campaigns.reduce((t, c) => t + c[key], 0);
const spend = +sum('spend').toFixed(2);
const clicks = sum('clicks');
const impressions = sum('impressions');
const results = sum('results');

return [{
  json: {
    period: rows[0] ? `${rows[0].date_start} to ${rows[0].date_stop}` : 'last 7 days',
    currency: settings.currency,
    result_name: settings.result_action,
    totals: {
      spend,
      impressions,
      clicks,
      ctr_pct: impressions ? +((clicks / impressions) * 100).toFixed(2) : 0,
      results,
      cost_per_result: results ? +(spend / results).toFixed(2) : null,
    },
    campaigns,
  },
}];

